('b4726e54-35ae-51bb-87b6-3760b50d00ef'::uuid,'F3-11','Corrective action and document revision register entry','Annex 3-L.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'{"fields": [{"key": "finding", "label": "Finding and source", "type": "textarea", "required": true, "hint": "IAT, exercise, event or audit"}, {"key": "root_cause", "label": "Root cause", "type": "textarea", "required": false}, {"key": "action", "label": "Corrective action", "type": "textarea", "required": true}, {"key": "owner", "label": "Accountable office", "type": "text", "required": true}, {"key": "due", "label": "Due date", "type": "date", "required": true}, {"key": "verification", "label": "Verification evidence", "type": "text", "required": false}, {"key": "closure", "label": "Closure", "type": "select", "required": false, "options": ["Open", "Closed", "Escalated"]}]}'::jsonb,'draft',1),
('1887530c-22c4-5afd-a2c4-b6144eec6693'::uuid,'EOC-F02','EOC opening and operational readiness checklist','Chapter 4 EOC-F02 (SOP 4-04 step 5).','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'{"fields": [{"key": "level", "label": "Alert status in force", "type": "select", "required": true, "options": ["White", "Blue", "Red"]}, {"key": "checked", "label": "Checked and ready", "type": "multiselect", "required": true, "options": ["Facility and safety", "Power and backup", "Communications (primary and backup)", "Roster and alternates", "Equipment and supplies", "Maps and data", "Records and logbook", "Shift plan", "Briefing held"]}, {"key": "gaps", "label": "Gaps and the office fixing each", "type": "textarea", "required": false}, {"key": "operational_period", "label": "First operational period", "type": "text", "required": true}]}'::jsonb,'draft',1),
('6dd398e2-5ac0-5b5e-bd76-b42c9a7c50c6'::uuid,'EOC-F03','Initial incident coordination and ICS interface record','Chapter 4 EOC-F03 (SOP 4-05).','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'{"fields": [{"key": "incident", "label": "Incident and location", "type": "text", "required": true}, {"key": "ic_position", "label": "Incident Commander / IMT (position and agency)", "type": "text", "required": true, "hint": "Position and agency, not a personal name"}, {"key": "command_post", "label": "Command post and contact channel", "type": "text", "required": true}, {"key": "objectives", "label": "Incident objectives received and operational period", "type": "textarea", "required": true}, {"key": "eoc_support", "label": "EOC support objectives and decisions needed", "type": "textarea", "required": true}, {"key": "liaison", "label": "Liaison arrangement and escalation route", "type": "textarea", "required": false}]}'::jsonb,'draft',1),
('ad6db068-6f20-51de-84bc-09f0edc8d69d'::uuid,'EOC-F04','Incident briefing and shift handover','Chapter 4 EOC-F04 (SOP 4-05 steps 6-7; SOP 4-04 step 6).','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'{"fields": [{"key": "situation", "label": "Situation, source and time", "type": "textarea", "required": true}, {"key": "objectives", "label": "Objectives", "type": "textarea", "required": true}, {"key": "open_tasks", "label": "Open tasks, requests and decisions", "type": "textarea", "required": true}, {"key": "risks", "label": "Risks and constraints", "type": "textarea", "required": false}, {"key": "next_review", "label": "Next briefing or handover time", "type": "text", "required": true}]}'::jsonb,'draft',1),
('48b7ccf3-2c40-5d7a-a666-0fe6bfacb4ce'::uuid,'ER-F01','Evacuation coordination and monitoring sheet','Chapter 4 ER-F01 (SOP 4-06). Counts only; no names.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'{"fields": [{"key": "decision_ref", "label": "Authorised decision or order (reference)", "type": "text", "required": true, "hint": "Who decided under which issuance"}, {"key": "areas", "label": "Barangays or puroks covered", "type": "textarea", "required": true}, {"key": "families_moved", "label": "Families moved (aggregate)", "type": "integer", "required": false}, {"key": "persons_moved", "label": "Persons moved (aggregate)", "type": "integer", "required": false}, {"key": "centres_open", "label": "Evacuation centres open", "type": "integer", "required": false}, {"key": "transport_access", "label": "Transport and access issues", "type": "textarea", "required": false}, {"key": "unmet_needs", "label": "Unmet needs and the office handling each", "type": "textarea", "required": false}]}'::jsonb,'draft',1),
('9039d834-9eb5-5d60-b3ab-69bca67857ee'::uuid,'ER-F02','Response deployment and safety coordination record','Chapter 4 ER-F02.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'{"fields": [{"key": "requesting_authority", "label": "Requesting authority", "type": "text", "required": true}, {"key": "task", "label": "Task and location", "type": "textarea", "required": true}, {"key": "lead_agency", "label": "Lead agency", "type": "text", "required": true}, {"key": "check_in", "label": "Check-in time", "type": "time", "required": false}, {"key": "safety", "label": "Safety briefing and hazards noted", "type": "textarea", "required": true}, {"key": "status", "label": "Status", "type": "select", "required": true, "options": ["Deployed", "On task", "Completed", "Withdrawn"]}]}'::jsonb,'draft',1),
